// @ts-nocheck
// GENERATED by scripts/sync-shared.mjs from the web app — do not edit; run `npm run sync:shared`.
// Dodge: a category comes up and everyone, the chosen player included, types one answer. The chosen player scores for
// every player who said the same thing; everyone else wants to dodge them. Exact matches are found here; close calls
// ("peperoni" for "pepperoni") wait for a short judge phase that the server feeds with `judged`, the way NPAT dig does.
// Pure: the server runs it for rooms.
import { categoryKey } from "../dodge/decks";
import { ANSWER_MAX, ANSWER_MS, JUDGE_MS, REVEAL_MS, WRITE_GRACE_MS, close, matchKey } from "../dodge/rules";
import { addCalls, initDrinks, type DrinkCall, type DrinkState } from "../party/drinks";
import { has, own } from "../party/own";
import { shuffle } from "../rng";

export type DodgeStatus = "chosen" | "match" | "dodge" | "blank";

export type DodgeRound = {
  category: string;
  chosen: string;
  /** What each player typed, trimmed; "" is a blank. */
  answers: Record<string, string>;
  status: Record<string, DodgeStatus>;
  /** Matches the judge called (close, not exact). */
  judged: string[];
  /** Close calls fell back to exact matches only: the judge was down, slow or skipped. */
  unchecked?: true;
  gained: Record<string, number>;
};

/** The round being judged: answers frozen at the close, exact matches found, close calls waiting for a verdict. */
export type Closing = { answers: Record<string, string>; matched: string[]; judged: string[]; pending: string[] };

export type DodgeState = {
  players: string[];
  decks: string[];
  /** One category per round, dealt at the start. */
  categories: string[];
  round: number;
  phase: "answer" | "judge" | "reveal";
  /** What each player has typed for the open round; cleared when it closes. */
  typed: Record<string, string>;
  locked: string[];
  closing: Closing | null;
  points: Record<string, number>;
  history: DodgeRound[];
  /** Players who left (from `settle`): not waited for, blank from then on, and their rounds as chosen are skipped. */
  gone: string[];
  phaseAt: number;
  startedAt: number;
  done: boolean;
  seed: number;
  drinks?: DrinkState;
};

/** What a seat is sent: see `redactFor`. `total` is how many rounds there are; `typedCount` how many have typed. */
export type DodgeView = DodgeState & { total: number; typedCount: number };

export type DodgeVerdict = { player: string; same: boolean };

export const chosen = (s: Pick<DodgeState, "players" | "round">): string => s.players[s.round % s.players.length]!;

export function init(o: { players: string[]; decks: string[]; categories: string[]; laps: number; avoid?: string[]; drinking?: boolean; seed: number; now: number }): DodgeState {
  const laps = Math.max(1, Math.min(3, Math.floor(Number.isFinite(o.laps) ? o.laps : 1)));
  const rounds = o.players.length * laps;
  const avoid = new Set(o.avoid ?? []);
  const unique = [...new Set(o.categories)];
  // Unseen categories first, then seen ones; a short deck goes round again in a new order.
  const [fresh, s1] = shuffle(unique.filter((c) => !avoid.has(categoryKey(c))), o.seed);
  const [seen, s2] = shuffle(unique.filter((c) => avoid.has(categoryKey(c))), s1);
  let seed = s2;
  let categories = [...fresh, ...seen];
  while (categories.length && categories.length < rounds) {
    const [more, s3] = shuffle(unique, seed);
    seed = s3;
    categories = [...categories, ...more];
  }
  categories = categories.slice(0, rounds);
  return {
    players: o.players, decks: o.decks, categories, round: 0, phase: "answer", typed: {}, locked: [], closing: null,
    points: Object.fromEntries(o.players.map((p) => [p, 0])), history: [], gone: [], phaseAt: o.now, startedAt: o.now,
    done: categories.length === 0, seed, ...(o.drinking ? { drinks: initDrinks(o.players) } : {}),
  };
}

const here = (s: DodgeState) => s.players.filter((p) => !s.gone.includes(p));
const answering = (s: DodgeState, now: number) => !s.done && s.phase === "answer" && now - s.phaseAt < ANSWER_MS + WRITE_GRACE_MS;

/** Saves (or replaces) a player's answer. Refused outside the answer phase, after locking, or if too long or not text. */
export function answer(s: DodgeState, by: string, text: unknown, now: number): DodgeState {
  if (!answering(s, now) || !s.players.includes(by) || s.locked.includes(by)) return s;
  if (typeof text !== "string" || text.length > ANSWER_MAX) return s;
  return { ...s, typed: { ...s.typed, [by]: text } };
}

/** A player submits early. The round closes once everyone still here has. */
export function lock(s: DodgeState, by: string, now: number): DodgeState {
  if (!answering(s, now) || !s.players.includes(by) || s.locked.includes(by)) return s;
  const t = { ...s, locked: [...s.locked, by] };
  return allLocked(t) ? close_(t, now) : t;
}

const allLocked = (s: DodgeState) => here(s).length > 0 && here(s).every((p) => s.locked.includes(p));

/** Answers freeze; exact matches with the chosen player count now, close calls go to the judge. */
function close_(s: DodgeState, now: number): DodgeState {
  const c = chosen(s);
  const answers = Object.fromEntries(s.players.map((p) => [p, s.gone.includes(p) ? "" : (own(s.typed, p) ?? "").trim()]));
  const target = matchKey(answers[c]!);
  const others = s.players.filter((p) => p !== c && matchKey(answers[p]!));
  const matched = target ? others.filter((p) => matchKey(answers[p]!) === target) : [];
  const pending = target ? others.filter((p) => !matched.includes(p) && close(answers[p]!, answers[c]!)) : [];
  const t: DodgeState = { ...s, typed: {}, locked: [], closing: { answers, matched, judged: [], pending } };
  return pending.length ? { ...t, phase: "judge", phaseAt: now } : reveal(t, now);
}

/** The close calls still waiting for the judge. */
export function pendingPairs(s: DodgeState): { player: string; category: string; chosen: string; answer: string }[] {
  if (s.done || s.phase !== "judge" || !s.closing) return [];
  const c = s.closing;
  return c.pending.map((p) => ({ player: p, category: s.categories[s.round]!, chosen: c.answers[chosen(s)]!, answer: c.answers[p]! }));
}

/** Applies the judge's verdicts to the calls still pending, and reveals once none are. */
export function judged(s: DodgeState, verdicts: DodgeVerdict[], now: number): DodgeState {
  if (s.done || s.phase !== "judge" || !s.closing || !Array.isArray(verdicts)) return s;
  let c = s.closing;
  for (const v of verdicts) {
    if (!v || typeof v.player !== "string" || typeof v.same !== "boolean" || !c.pending.includes(v.player)) continue;
    c = { ...c, pending: c.pending.filter((p) => p !== v.player), ...(v.same ? { matched: [...c.matched, v.player], judged: [...c.judged, v.player] } : {}) };
  }
  if (c === s.closing) return s;
  const t = { ...s, closing: c };
  return c.pending.length ? t : reveal(t, now);
}

/** Scores the round, pours a sip for each matcher and shows the reveal. Pending close calls left now are dodges. */
function reveal(s: DodgeState, now: number): DodgeState {
  const c = s.closing!;
  const who = chosen(s);
  const blank = (p: string) => !matchKey(c.answers[p]!);
  const status: Record<string, DodgeStatus> = Object.fromEntries(s.players.map((p) => [p,
    p === who ? "chosen" : blank(p) ? "blank" : c.matched.includes(p) ? "match" : "dodge"]));
  const gained: Record<string, number> = Object.fromEntries(s.players.map((p) => [p,
    p === who ? c.matched.length : status[p] === "match" ? -1 : status[p] === "dodge" ? 1 : 0]));
  const round: DodgeRound = {
    category: s.categories[s.round]!, chosen: who, answers: c.answers, status, judged: c.judged, gained,
    ...(c.pending.length ? { unchecked: true as const } : {}),
  };
  const points = Object.fromEntries(s.players.map((p) => [p, (own(s.points, p) ?? 0) + gained[p]!]));
  const calls: DrinkCall[] = c.matched.map((p) => ({ to: p, sips: 1, reason: `You said what ${who} said` }));
  const drinks = s.drinks ? addCalls(s.drinks, calls, s.players) : undefined;
  return { ...s, phase: "reveal", closing: null, points, history: [...s.history, round], ...(drinks ? { drinks } : {}), phaseAt: now };
}

/** The next round, skipping any whose chosen player has left; done after the last. */
function advance(s: DodgeState, now: number): DodgeState {
  let round = s.round + 1;
  while (round < s.categories.length && s.gone.includes(chosen({ players: s.players, round }))) round++;
  if (round >= s.categories.length) return { ...s, typed: {}, locked: [], done: true, phaseAt: now };
  return { ...s, round, phase: "answer", typed: {}, locked: [], closing: null, phaseAt: now };
}

/** Host skip: closes the answers, ends the judge with exact matches only, or ends the reveal. */
export function next(s: DodgeState, now: number): DodgeState {
  if (s.done) return s;
  if (s.phase === "answer") return close_(s, now);
  if (s.phase === "judge") return reveal(s, now);
  return advance(s, now);
}

/** Clocks, one step per call. Deadlines are inclusive. */
export function tick(s: DodgeState, now: number): DodgeState {
  if (s.done) return s;
  const t = now - s.phaseAt;
  if (s.phase === "answer") return t >= ANSWER_MS + WRITE_GRACE_MS ? close_(s, now) : s;
  if (s.phase === "judge") return t >= JUDGE_MS ? reveal(s, now) : s;
  return t >= REVEAL_MS ? advance(s, now) : s;
}

/** Records who has left, then skips a round whose chosen player has gone or closes one only waiting on them. */
export function settle(s: DodgeState, gone: string[], now: number): DodgeState {
  if (s.done) return s;
  const g = s.players.filter((p) => gone.includes(p));
  const t = g.length === s.gone.length && g.every((p) => s.gone.includes(p)) ? s : { ...s, gone: g };
  if (t.phase !== "answer") return t;
  if (t.gone.includes(chosen(t))) return advance(t, now);
  return allLocked(t) ? close_(t, now) : t;
}

/** Top points; ties share. */
export function winners(s: DodgeState): string[] {
  const pts = (p: string) => own(s.points, p) ?? 0;
  const top = Math.max(...s.players.map(pts));
  return s.players.filter((p) => pts(p) === top);
}

/** The categories played, for the room's `seen` list. */
export function seenKeys(s: DodgeState): string[] {
  return s.history.map((h) => categoryKey(h.category));
}

/**
 * What one seat may see. Never the seed, and never categories still to come. While answering, only `me`'s own typing
 * (nothing for a screen) plus how many players have typed. While judging, no answers: they flip at the reveal.
 */
export function redactFor(s: DodgeState, me: string | null): DodgeView {
  const open = s.done;
  const asking = !s.done && s.phase === "answer";
  const typed = asking && me !== null && has(s.typed, me) ? { [me]: s.typed[me]! } : {};
  const typedCount = asking ? Object.values(s.typed).filter((t) => matchKey(t)).length : 0;
  return {
    ...s, seed: 0, typed, typedCount, total: s.categories.length,
    categories: open ? s.categories : s.categories.slice(0, s.round + 1),
    closing: null,
  };
}
